     1	package com.loja.domain.strategies.coupon;
     2	
     3	import com.loja.domain.entities.*;
     4	import com.loja.repositories.ProductRepository;
     5	
     6	import java.util.List;
     7	import java.util.Map;
     8	import java.util.stream.Collectors;
     9	
    10	public class Buy3Pay2Coupon implements CouponStrategy {
    11	    private final ProductRepository productRepository;
    12	
    13	    public Buy3Pay2Coupon(ProductRepository productRepository) {
    14	        this.productRepository = productRepository;
    15	    }
    16	
    17	    @Override
    18	    public Money calculateDiscount(Money productsSubtotal, Money shippingCost, List<OrderItem> items, String customerCpf) {
    19	        Money totalDiscount = Money.zero();
    20	
    21	        Map<String, Integer> quantitiesBySku = items.stream()
    22	                .collect(Collectors.toMap(OrderItem::getSku, OrderItem::getQuantity));
    23	
    24	        for (Map.Entry<String, Integer> entry : quantitiesBySku.entrySet()) {
    25	            String sku = entry.getKey();
    26	            int quantity = entry.getValue();
    27	
    28	            if (quantity >= 3) {
    29	                int freeUnits = quantity / 3;
    30	                Product product = productRepository.findBySku(sku);
    31	                Money unitPrice = product.getPrice();
    32	                Money discountForSku = unitPrice.multiply(freeUnits);
    33	                totalDiscount = totalDiscount.add(discountForSku);
    34	            }
    35	        }
    36	
    37	        return totalDiscount;
    38	    }
    39	
    40	    @Override
    41	    public boolean isApplicable(Money productsSubtotal, Money shippingCost, List<OrderItem> items, String customerCpf, ShippingMethod shippingMethod) {
    42	        return true;
    43	    }
    44	
    45	    @Override
    46	    public CouponCode getCode() {
    47	        return CouponCode.BUY3PAY2;
    48	    }
    49	}
