     1	package com.loja.domain.strategies.shipping;
     2	
     3	import com.loja.domain.entities.Money;
     4	import com.loja.domain.entities.Region;
     5	import com.loja.domain.entities.ShippingMethod;
     6	import com.loja.infrastructure.TransLogClient;
     7	
     8	public class EconomyShipping implements ShippingStrategy {
     9	    private final TransLogClient transLogClient;
    10	
    11	    public EconomyShipping(TransLogClient transLogClient) {
    12	        this.transLogClient = transLogClient;
    13	    }
    14	
    15	    @Override
    16	    public Money calculateCost(String zipCode, double weightKg) throws ShippingUnavailableException {
    17	        try {
    18	            TransLogClient.TransLogQuote quote = transLogClient.getQuote(
    19	                    zipCode, weightKg, TransLogClient.TransLogService.ECONOMY);
    20	            return Money.of(quote.getPriceReais());
    21	        } catch (TransLogClient.ZipNotServedException e) {
    22	            throw new ShippingUnavailableException("ZIP not served", e);
    23	        } catch (TransLogClient.TransLogException e) {
    24	            throw new ShippingUnavailableException("Carrier unavailable", e);
    25	        }
    26	    }
    27	
    28	    @Override
    29	    public int calculateDeliveryDays(Region region) {
    30	        try {
    31	            TransLogClient.TransLogQuote quote = transLogClient.getQuote(
    32	                    "00000000", 1.0, TransLogClient.TransLogService.ECONOMY);
    33	            int baseDays = quote.getDeliveryDays();
    34	            return baseDays + getRegionalDelay(region);
    35	        } catch (Exception e) {
    36	            return 7 + getRegionalDelay(region);
    37	        }
    38	    }
    39	
    40	    private int getRegionalDelay(Region region) {
    41	        return switch (region) {
    42	            case NORTH -> 3;
    43	            case NORTHEAST -> 2;
    44	            default -> 0;
    45	        };
    46	    }
    47	
    48	    @Override
    49	    public boolean isAvailable(double weightKg, String zipCode) {
    50	        try {
    51	            calculateCost(zipCode, weightKg);
    52	            return true;
    53	        } catch (ShippingUnavailableException e) {
    54	            return false;
    55	        }
    56	    }
    57	
    58	    @Override
    59	    public ShippingMethod getMethod() {
    60	        return ShippingMethod.ECONOMY;
    61	    }
    62	}
