     6	public class Money {
     7	    private static final int SCALE = 2;
     8	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
     9	
    10	    private final BigDecimal amount;
    11	
    12	    private Money(BigDecimal amount) {
    13	        this.amount = amount.setScale(SCALE, ROUNDING_MODE);
    14	    }
    15	
    16	    public static Money of(double value) {
    17	        return new Money(BigDecimal.valueOf(value));
    18	    }
    19	
    20	    public static Money of(BigDecimal value) {
