     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	
     8	public class CreditCardPayment implements PaymentMethodStrategy {
     9	    private static final double MONTHLY_INTEREST_RATE = 0.0199;
    10	    private static final int MAX_INSTALLMENTS_NO_INTEREST = 3;
    11	    private static final int MAX_INSTALLMENTS = 12;
    12	
    13	    @Override
    14	    public Money calculateAdjustment(Money orderTotal, int installments, boolean hasCoupon) {
    15	        if (installments <= MAX_INSTALLMENTS_NO_INTEREST) {
    16	            return Money.zero();
    17	        }
    18	
    19	        Money installmentAmount = calculateInstallmentWithInterest(orderTotal, installments);
    20	        Money finalTotal = installmentAmount.multiply(installments);
    21	        return finalTotal.subtract(orderTotal);
    22	    }
    23	
    24	    @Override
    25	    public int calculateInstallments(int requestedInstallments) {
    26	        if (requestedInstallments < 1) {
    27	            return 1;
    28	        }
    29	        if (requestedInstallments > MAX_INSTALLMENTS) {
    30	            return MAX_INSTALLMENTS;
    31	        }
    32	        return requestedInstallments;
    33	    }
    34	
    35	    @Override
    36	    public Money calculateInstallmentAmount(Money finalTotal, int installments) {
    37	        return finalTotal.divide(installments);
    38	    }
    39	
    40	    private Money calculateInstallmentWithInterest(Money principal, int installments) {
    41	        BigDecimal rate = BigDecimal.valueOf(MONTHLY_INTEREST_RATE);
    42	        BigDecimal numInstallments = BigDecimal.valueOf(installments);
    43	
    44	        BigDecimal onePlusRate = BigDecimal.ONE.add(rate);
    45	        BigDecimal denominator = BigDecimal.ONE.subtract(
    46	                onePlusRate.pow(-installments, new java.math.MathContext(10, RoundingMode.HALF_EVEN))
    47	        );
    48	
    49	        BigDecimal installment = principal.toBigDecimal()
    50	                .multiply(rate)
    51	                .divide(denominator, 2, RoundingMode.HALF_EVEN);
    52	
    53	        return Money.of(installment);
    54	    }
    55	
    56	
    57	    @Override
    58	    public boolean isAvailable(Money orderTotal) {
    59	        return true;
    60	    }
    61	
    62	    @Override
    63	    public PaymentMethod getMethod() {
    64	        return PaymentMethod.CREDIT_CARD;
    65	    }
    66	}
