  1	package com.loja.services;
  2	
  3	import com.loja.domain.entities.*;
  4	import com.loja.domain.strategies.club.ClubTierStrategy;
  5	import com.loja.domain.strategies.coupon.CouponStrategy;
  6	import com.loja.domain.strategies.payment.PaymentMethodStrategy;
  7	import com.loja.domain.strategies.shipping.ShippingStrategy;
  8	import com.loja.domain.strategies.shipping.ShippingUnavailableException;
  9	import com.loja.repositories.ProductRepository;
 10	
 11	import java.util.List;
 12	import java.util.Map;
 13	
 14	public class CheckoutService {
 15	    private static final double MAX_COUPON_DISCOUNT_PERCENT = 0.30;
 16	
 17	    private final ProductRepository productRepository;
 18	    private final Map<ShippingMethod, ShippingStrategy> shippingStrategies;
 19	    private final Map<CouponCode, CouponStrategy> couponStrategies;
 20	    private final Map<ClubTier, ClubTierStrategy> clubTierStrategies;
 21	    private final Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies;
 22	
 23	    public CheckoutService(
 24	            ProductRepository productRepository,
 25	            Map<ShippingMethod, ShippingStrategy> shippingStrategies,
 26	            Map<CouponCode, CouponStrategy> couponStrategies,
 27	            Map<ClubTier, ClubTierStrategy> clubTierStrategies,
 28	            Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies) {
 29	        this.productRepository = productRepository;
 30	        this.shippingStrategies = shippingStrategies;
 31	        this.couponStrategies = couponStrategies;
 32	        this.clubTierStrategies = clubTierStrategies;
 33	        this.paymentMethodStrategies = paymentMethodStrategies;
 34	    }
 35	
 36	    public OrderSummary calculateSummary(CheckoutRequest request) throws ShippingUnavailableException {
 37	        Money productsSubtotal = calculateProductsSubtotal(request.items());
 38	
 39	        ShippingStrategy shippingStrategy = shippingStrategies.get(request.shippingMethod());
 40	        Money rawShippingCost = shippingStrategy.calculateCost(request.zipCode(), calculateTotalWeight(request.items()));
 41	        int baseDeliveryDays = shippingStrategy.calculateDeliveryDays(request.region());
 42	
 43	        CouponStrategy couponStrategy = request.coupon() != null ? couponStrategies.get(request.coupon()) : null;
 44	        Money couponDiscount = Money.zero();
 45	        if (couponStrategy != null) {
 46	            couponDiscount = couponStrategy.calculateDiscount(
 47	                    productsSubtotal,
 48	                    rawShippingCost,
 49	                    request.items(),
 50	                    request.customerCpf()
 51	            );
 52	            Money maxDiscount = productsSubtotal.multiply(MAX_COUPON_DISCOUNT_PERCENT);
 53	            if (couponDiscount.isGreaterThan(maxDiscount)) {
 54	                couponDiscount = maxDiscount;
 55	            }
 56	        }
 57	
 58	        Money insurance = calculateInsurance(productsSubtotal, request.region());
 59	
 60	        ClubTierStrategy clubStrategy = clubTierStrategies.get(request.clubTier());
 61	        Money adjustedShippingCost = clubStrategy.adjustShippingCost(rawShippingCost, request.shippingMethod());
 62	
 63	        Money orderTotal = productsSubtotal
 64	                .subtract(couponDiscount)
 65	                .add(adjustedShippingCost)
 66	                .add(insurance);
 67	
 68	        PaymentMethodStrategy paymentStrategy = paymentMethodStrategies.get(request.paymentMethod());
 69	        int installments = paymentStrategy.calculateInstallments(request.installments());
 70	        Money paymentAdjustment = paymentStrategy.calculateAdjustment(
 71	                orderTotal,
 72	                installments,
 73	                request.coupon() != null
 74	        );
 75	
 76	        Money finalTotal = orderTotal.add(paymentAdjustment);
 77	        Money installmentAmount = paymentStrategy.calculateInstallmentAmount(finalTotal, installments);
 78	
 79	        Money nextPurchaseCredit = clubStrategy.calculateCredit(productsSubtotal);
 80	        boolean gift = clubStrategy.hasGift(productsSubtotal);
 81	
 82	        return new OrderSummary(
 83	                productsSubtotal,
 84	                couponDiscount,
 85	                adjustedShippingCost,
 86	                baseDeliveryDays,
 87	                insurance,
 88	                paymentAdjustment,
 89	                finalTotal,
 90	                installments,
 91	                installmentAmount,
 92	                nextPurchaseCredit,
 93	                gift
 94	        );
 95	    }
 96	
 97	    private Money calculateProductsSubtotal(List<OrderItem> items) {
 98	        Money subtotal = Money.zero();
 99	        for (OrderItem item : items) {
100	            Product product = productRepository.findBySku(item.getSku());
101	            Money itemTotal = product.getPrice().multiply(item.getQuantity());
102	            subtotal = subtotal.add(itemTotal);
103	        }
104	        return subtotal;
105	    }
106	
107	    private double calculateTotalWeight(List<OrderItem> items) {
108	        double totalWeight = 0;
109	        for (OrderItem item : items) {
110	            Product product = productRepository.findBySku(item.getSku());
111	            totalWeight += product.getWeightKg() * item.getQuantity();
112	        }
113	        return totalWeight;
114	    }
115	
116	    private Money calculateInsurance(Money productsSubtotal, Region region) {
117	        double percentage = switch (region) {
118	            case SOUTHEAST, SOUTH -> 0.01;
119	            case MIDWEST -> 0.015;
120	            case NORTHEAST -> 0.02;
121	            case NORTH -> 0.025;
122	        };
123	
124	        Money insurance = productsSubtotal.multiply(percentage);
125	
126	        Money limit = switch (region) {
127	            case NORTH, NORTHEAST -> Money.of(30.00);
128	            case SOUTHEAST, SOUTH, MIDWEST -> null;
129	        };
130	
131	        if (limit != null && insurance.isGreaterThan(limit)) {
132	            return limit;
133	        }
134	
135	        return insurance;
136	    }
137	
138	    public record CheckoutRequest(
139	            String customerCpf,
140	            List<OrderItem> items,
141	            String zipCode,
142	            Region region,
143	            ShippingMethod shippingMethod,
144	            CouponCode coupon,
145	            PaymentMethod paymentMethod,
146	            int installments,
147	            ClubTier clubTier
148	    ) {
149	    }
150	}
151	package com.loja.services;
152	
153	import com.loja.domain.entities.*;
154	import com.loja.domain.strategies.coupon.CouponStrategy;
155	import com.loja.domain.strategies.payment.PaymentMethodStrategy;
156	import com.loja.domain.strategies.shipping.ShippingStrategy;
157	import com.loja.repositories.OrderRepository;
158	import com.loja.repositories.ProductRepository;
159	
160	import java.util.HashSet;
161	import java.util.List;
162	import java.util.Map;
163	import java.util.Set;
164	
165	public class ValidationService {
166	    private final ProductRepository productRepository;
167	    private final OrderRepository orderRepository;
168	    private final Map<ShippingMethod, ShippingStrategy> shippingStrategies;
169	    private final Map<CouponCode, CouponStrategy> couponStrategies;
170	    private final Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies;
171	
172	    public ValidationService(
173	            ProductRepository productRepository,
174	            OrderRepository orderRepository,
175	            Map<ShippingMethod, ShippingStrategy> shippingStrategies,
176	            Map<CouponCode, CouponStrategy> couponStrategies,
177	            Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies) {
178	        this.productRepository = productRepository;
179	        this.orderRepository = orderRepository;
180	        this.shippingStrategies = shippingStrategies;
181	        this.couponStrategies = couponStrategies;
182	        this.paymentMethodStrategies = paymentMethodStrategies;
183	    }
184	
185	    public void validateCheckoutRequest(CheckoutService.CheckoutRequest request) throws ValidationException {
186	        validateOrderStructure(request);
187	        validateProducts(request.items());
188	        validateClubTier(request.clubTier());
189	        validateRegion(request.region());
190	        validateZipCode(request.zipCode());
191	        validateShippingMethod(request.shippingMethod(), request.items(), request.zipCode());
192	        validateCoupon(request);
193	        validatePaymentMethod(request);
194	    }
195	
196	    private void validateOrderStructure(CheckoutService.CheckoutRequest request) throws ValidationException {
197	        if (request.items() == null || request.items().isEmpty()) {
198	            throw new ValidationException("INVALID_ORDER", "Cart is empty");
199	        }
200	
201	        if (request.customerCpf() == null || request.customerCpf().isBlank()) {
202	            throw new ValidationException("INVALID_ORDER", "Customer CPF is required");
203	        }
204	
205	        Set<String> skus = new HashSet<>();
206	        for (OrderItem item : request.items()) {
207	            if (item.getSku() == null || item.getSku().isBlank()) {
208	                throw new ValidationException("INVALID_ORDER", "Item SKU is required");
209	            }
210	
211	            if (item.getQuantity() <= 0) {
212	                throw new ValidationException("INVALID_ORDER", "Item quantity must be positive");
213	            }
214	
215	            if (skus.contains(item.getSku())) {
216	                throw new ValidationException("INVALID_ORDER", "Duplicate SKU in cart: " + item.getSku());
217	            }
218	            skus.add(item.getSku());
219	        }
220	    }
221	
222	    private void validateProducts(List<OrderItem> items) throws ValidationException {
223	        for (OrderItem item : items) {
224	            Product product = productRepository.findBySku(item.getSku());
225	
226	            if (product == null) {
227	                throw new ValidationException("UNKNOWN_PRODUCT", "Product not found: " + item.getSku());
228	            }
229	
230	            if (product.isDiscontinued()) {
231	                throw new ValidationException("PRODUCT_DISCONTINUED", "Product discontinued: " + item.getSku());
232	            }
233	
234	            if (!product.hasStock(item.getQuantity())) {
235	                throw new ValidationException("INSUFFICIENT_STOCK", "Insufficient stock for product: " + item.getSku());
236	            }
237	        }
238	    }
239	
240	    private void validateClubTier(ClubTier clubTier) throws ValidationException {
241	        if (clubTier == null) {
242	            throw new ValidationException("INVALID_CLUB_TIER", "Club tier is required");
243	        }
244	    }
245	
246	    private void validateRegion(Region region) throws ValidationException {
247	        if (region == null) {
248	            throw new ValidationException("INVALID_REGION", "Region is required");
249	        }
250	    }
251	
252	    private void validateZipCode(String zipCode) throws ValidationException {
253	        if (zipCode == null || !zipCode.matches("\\d{8}")) {
254	            throw new ValidationException("INVALID_ZIP_CODE", "Invalid ZIP code format");
255	        }
256	    }
257	
258	    private void validateShippingMethod(ShippingMethod shippingMethod, List<OrderItem> items, String zipCode) throws ValidationException {
259	        if (shippingMethod == null) {
260	            throw new ValidationException("INVALID_SHIPPING_METHOD", "Shipping method is required");
261	        }
262	
263	        ShippingStrategy strategy = shippingStrategies.get(shippingMethod);
264	        if (strategy == null) {
265	            throw new ValidationException("INVALID_SHIPPING_METHOD", "Invalid shipping method");
266	        }
267	
268	        double totalWeight = calculateTotalWeight(items);
269	
270	        try {
271	            Money cost = strategy.calculateCost(zipCode, totalWeight);
272	            if (!strategy.isAvailable(totalWeight, zipCode)) {
273	                throw new ValidationException("SHIPPING_METHOD_UNAVAILABLE", "Shipping method not available");
274	            }
275	        } catch (Exception e) {
276	            if (e.getMessage() != null && e.getMessage().contains("unavailable")) {
277	                throw new ValidationException("CARRIER_UNAVAILABLE", "Carrier unavailable");
278	            }
279	            if (e.getMessage() != null && e.getMessage().contains("not served")) {
280	                throw new ValidationException("SHIPPING_METHOD_UNAVAILABLE", "Shipping method not available for this location");
281	            }
282	            throw new ValidationException("CARRIER_UNAVAILABLE", "Carrier unavailable");
283	        }
284	    }
285	
286	    private void validateCoupon(CheckoutService.CheckoutRequest request) throws ValidationException {
287	        if (request.coupon() == null) {
288	            return;
289	        }
290	
291	        CouponStrategy strategy = couponStrategies.get(request.coupon());
292	        if (strategy == null) {
293	            throw new ValidationException("INVALID_COUPON", "Invalid coupon code");
294	        }
295	
296	        Money productsSubtotal = calculateProductsSubtotal(request.items());
297	        Money shippingCost = Money.zero();
298	        try {
299	            shippingCost = shippingStrategies.get(request.shippingMethod())
300	                    .calculateCost(request.zipCode(), calculateTotalWeight(request.items()));
301	        } catch (Exception e) {
302	        }
303	
304	        if (!strategy.isApplicable(
305	                productsSubtotal,
306	                shippingCost,
307	                request.items(),
308	                request.customerCpf(),
309	                request.shippingMethod())) {
310	            throw new ValidationException("COUPON_NOT_APPLICABLE", "Coupon not applicable to this order");
311	        }
312	    }
313	
314	    private void validatePaymentMethod(CheckoutService.CheckoutRequest request) throws ValidationException {
315	        if (request.paymentMethod() == null) {
316	            throw new ValidationException("INVALID_PAYMENT_METHOD", "Payment method is required");
317	        }
318	
319	        PaymentMethodStrategy strategy = paymentMethodStrategies.get(request.paymentMethod());
320	        if (strategy == null) {
321	            throw new ValidationException("INVALID_PAYMENT_METHOD", "Invalid payment method");
322	        }
323	
324	        int installments = request.installments();
325	        if (request.paymentMethod() == PaymentMethod.PIX || request.paymentMethod() == PaymentMethod.BANK_SLIP) {
326	            if (installments != 1 && installments != 0) {
327	                throw new ValidationException("INVALID_INSTALLMENTS", "PIX and bank slip must be paid in full");
328	            }
329	        } else if (request.paymentMethod() == PaymentMethod.CREDIT_CARD) {
330	            if (installments < 1 || installments > 12) {
331	                throw new ValidationException("INVALID_INSTALLMENTS", "Credit card installments must be between 1 and 12");
332	            }
333	        }
334	
335	        Money productsSubtotal = calculateProductsSubtotal(request.items());
336	        if (!strategy.isAvailable(productsSubtotal)) {
337	            throw new ValidationException("PAYMENT_METHOD_UNAVAILABLE", "Payment method not available for this order total");
338	        }
339	    }
340	
341	    private Money calculateProductsSubtotal(List<OrderItem> items) {
342	        Money subtotal = Money.zero();
343	        for (OrderItem item : items) {
344	            Product product = productRepository.findBySku(item.getSku());
345	            subtotal = subtotal.add(product.getPrice().multiply(item.getQuantity()));
346	        }
347	        return subtotal;
348	    }
349	
350	    private double calculateTotalWeight(List<OrderItem> items) {
351	        double totalWeight = 0;
352	        for (OrderItem item : items) {
353	            Product product = productRepository.findBySku(item.getSku());
354	            totalWeight += product.getWeightKg() * item.getQuantity();
355	        }
356	        return totalWeight;
357	    }
358	
359	    public static class ValidationException extends Exception {
360	        private final String errorCode;
361	
362	        public ValidationException(String errorCode, String message) {
363	            super(message);
364	            this.errorCode = errorCode;
365	        }
366	
367	        public String getErrorCode() {
368	            return errorCode;
369	        }
370	    }
371	}

