 77	        Money installmentAmount = paymentStrategy.calculateInstallmentAmount(finalTotal, installments);
 78	
 79	        Money nextPurchaseCredit = clubStrategy.calculateCredit(productsSubtotal);
 80	        boolean gift = clubStrategy.hasGift(productsSubtotal);
 81	
 82	        return new OrderSummary(
 83	                productsSubtotal,
 84	                couponDiscount,
 85	                adjustedShippingCost,
 86	                baseDeliveryDays,
 87	                insurance,
 88	                paymentAdjustment,
 89	                finalTotal,
 90	                installments,
 91	                installmentAmount,
 92	                nextPurchaseCredit,
 93	                gift
 94	        );
 95	    }
