    12	import com.loja.domain.strategies.shipping.*;
    13	import com.loja.infrastructure.Database;
    14	import com.loja.infrastructure.TransLogClient;
    15	import com.loja.repositories.*;
    16	import com.loja.repositories.impl.*;
    17	import com.loja.services.CheckoutService;
