     1	package com.loja.infrastructure;
     2	
     3	import com.google.gson.Gson;
     4	import com.google.gson.JsonObject;
     5	
     6	import java.io.IOException;
     7	import java.net.URI;
     8	import java.net.http.HttpClient;
     9	import java.net.http.HttpRequest;
    10	import java.net.http.HttpResponse;
    11	import java.time.Duration;
    12	
    13	public class TransLogClient {
    14	    private final String baseUrl;
    15	    private final HttpClient httpClient;
    16	    private final Gson gson;
    17	
    18	    public TransLogClient(String baseUrl) {
    19	        this.baseUrl = baseUrl;
    20	        this.httpClient = HttpClient.newBuilder()
    21	                .connectTimeout(Duration.ofSeconds(2))
    22	                .build();
    23	        this.gson = new Gson();
    24	    }
    25	
    26	    public TransLogQuote getQuote(String zipCode, double weightKg, TransLogService service) throws TransLogException {
    27	        int weightG = (int) (weightKg * 1000);
    28	        String serviceCode = service == TransLogService.ECONOMY ? "STD" : "EXP";
    29	
    30	        String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
    31	                baseUrl, zipCode, weightG, serviceCode);
    32	
    33	        HttpRequest request = HttpRequest.newBuilder()
    34	                .uri(URI.create(url))
    35	                .timeout(Duration.ofSeconds(2))
    36	                .GET()
    37	                .build();
    38	
    39	        try {
    40	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
    41	
    42	            if (response.statusCode() != 200) {
    43	                throw new TransLogException("TransLog returned status " + response.statusCode());
    44	            }
    45	
    46	            JsonObject json = gson.fromJson(response.body(), JsonObject.class);
    47	
    48	            if (json.has("error")) {
    49	                String error = json.get("error").getAsString();
    50	                if ("ZIP_NOT_SERVED".equals(error)) {
    51	                    throw new ZipNotServedException("ZIP not served by TransLog");
    52	                }
    53	                throw new TransLogException("TransLog error: " + error);
    54	            }
    55	
    56	            int priceCents = json.get("price_cents").getAsInt();
    57	            int etaHours = json.get("eta_hours").getAsInt();
    58	
    59	            return new TransLogQuote(priceCents, etaHours);
    60	
    61	        } catch (IOException | InterruptedException e) {
    62	            throw new TransLogException("Failed to connect to TransLog", e);
    63	        }
    64	    }
    65	
    66	    public enum TransLogService {
    67	        ECONOMY,
    68	        EXPRESS
    69	    }
    70	
    71	    public static class TransLogQuote {
    72	        private final int priceCents;
    73	        private final int etaHours;
    74	
    75	        public TransLogQuote(int priceCents, int etaHours) {
    76	            this.priceCents = priceCents;
    77	            this.etaHours = etaHours;
    78	        }
    79	
    80	        public double getPriceReais() {
    81	            return priceCents / 100.0;
    82	        }
    83	
    84	        public int getDeliveryDays() {
    85	            return (int) Math.ceil(etaHours / 24.0);
    86	        }
    87	    }
    88	
    89	    public static class TransLogException extends Exception {
    90	        public TransLogException(String message) {
    91	            super(message);
    92	        }
    93	
    94	        public TransLogException(String message, Throwable cause) {
    95	            super(message, cause);
    96	        }
    97	    }
    98	
    99	    public static class ZipNotServedException extends TransLogException {
   100	        public ZipNotServedException(String message) {
   101	            super(message);
   102	        }
   103	    }
   104	}
